import type { MetadataRoute } from "next";

/**
 * Dynamic robots.txt — generated by Next.js at /robots.txt.
 * Replaces the static /public/robots.txt with a version that
 * includes the canonical sitemap URL and comprehensive rules.
 */
export default function robots(): MetadataRoute.Robots {
  return {
    rules: [
      {
        userAgent: "Googlebot",
        allow: "/",
        disallow: ["/admin", "/api/"],
      },
      {
        userAgent: "Bingbot",
        allow: "/",
        disallow: ["/admin", "/api/"],
      },
      {
        userAgent: "Twitterbot",
        allow: "/",
      },
      {
        userAgent: "facebookexternalhit",
        allow: "/",
      },
      {
        userAgent: "*",
        allow: "/",
        disallow: ["/admin", "/api/", "/*#/admin"],
      },
    ],
    sitemap: "https://www.skyoragroup.com/sitemap.xml",
  };
}
